// ── Permutations — O(n! * n) ──────────────────────────────────
// Generate all n! orderings of nums.
function permutations(nums) {
  const result = [];
  const used   = new Array(nums.length).fill(false);
  const path   = [];

  function backtrack() {
    // Base case: goal reached
    if (path.length === nums.length) {
      result.push([...path]); // snapshot — path is mutated, so copy it
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;        // pruning: already placed
      used[i] = true;               // choose
      path.push(nums[i]);
      backtrack();                  // explore
      path.pop();                   // unchoose
      used[i] = false;
    }
  }

  backtrack();
  return result;
}
console.log(permutations([1, 2, 3]).length); // 6

// ── Subsets (Power Set) — O(2^n * n) ─────────────────────────
function subsets(nums) {
  const result = [];
  function backtrack(start, path) {
    result.push([...path]);         // every prefix is a valid subset
    for (let i = start; i < nums.length; i++) {
      path.push(nums[i]);           // choose: include nums[i]
      backtrack(i + 1, path);      // explore remaining elements only
      path.pop();                   // unchoose: exclude nums[i]
    }
  }
  backtrack(0, []);
  return result;
}
console.log(subsets([1, 2, 3]).length); // 8

// ── Combination Sum — subsets that sum to target ──────────────
// Each element may be reused. Input sorted ascending for pruning.
function combinationSum(candidates, target) {
  const result = [];
  candidates.sort((a, b) => a - b);

  function backtrack(start, path, remaining) {
    if (remaining === 0) { result.push([...path]); return; }
    for (let i = start; i < candidates.length; i++) {
      if (candidates[i] > remaining) break; // sorted: all further > remaining
      path.push(candidates[i]);
      backtrack(i, path, remaining - candidates[i]); // reuse allowed: pass i, not i+1
      path.pop();
    }
  }

  backtrack(0, [], target);
  return result;
}
console.log(combinationSum([2, 3, 6, 7], 7));
// [[2,2,3],[7]]

// ── N-Queens — O(n!) worst-case, O(n) space ───────────────────
// Returns all board configurations as arrays of strings.
function solveNQueens(n) {
  const solutions = [];
  const cols  = new Set(); // attacked columns
  const diag1 = new Set(); // attacked \ diagonals: row - col
  const diag2 = new Set(); // attacked / diagonals: row + col
  const board = [];         // board[row] = column of queen in that row

  function backtrack(row) {
    if (row === n) {
      // All n queens placed — convert to string representation
      solutions.push(
        board.map(col => '.'.repeat(col) + 'Q' + '.'.repeat(n - col - 1))
      );
      return;
    }
    for (let col = 0; col < n; col++) {
      // Constraint check BEFORE recursing (more efficient)
      if (cols.has(col) || diag1.has(row - col) || diag2.has(row + col)) continue;

      // Choose
      cols.add(col); diag1.add(row - col); diag2.add(row + col);
      board.push(col);

      backtrack(row + 1); // Explore

      // Unchoose
      board.pop();
      cols.delete(col); diag1.delete(row - col); diag2.delete(row + col);
    }
  }

  backtrack(0);
  return solutions;
}

console.log(solveNQueens(4).length);  // 2
console.log(solveNQueens(8).length);  // 92
console.log(solveNQueens(13).length); // 73712

// ── Count-only variant — no board allocation, faster ──────────
function countNQueens(n) {
  let count = 0;
  const cols = new Set(), d1 = new Set(), d2 = new Set();
  function bt(row) {
    if (row === n) { count++; return; }
    for (let c = 0; c < n; c++) {
      if (cols.has(c) || d1.has(row - c) || d2.has(row + c)) continue;
      cols.add(c); d1.add(row - c); d2.add(row + c);
      bt(row + 1);
      cols.delete(c); d1.delete(row - c); d2.delete(row + c);
    }
  }
  bt(0);
  return count;
}
